-- One-time recovery codes for churned users.
--
-- A recovery code is generated by an admin for a user whose subscription has
-- canceled, is past due, trialing-expired, or who never subscribed. The code is
-- sent to the user (for example by email) and redeemed in-app through a modal.
-- Redeeming a code marks it used and grants a 14-day access extension through the
-- existing public.subscription_extensions table, so every access check
-- (guard, edge functions, trade worker) treats the grant exactly like an admin
-- grant: Advanced access while the 14-day window is live.
--
-- A code is tied to one user and can be used once. The user must be signed in as
-- that user to redeem it, so codes cannot be shared or reused.

create table if not exists public.subscription_recovery_codes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  code text not null unique,
  days integer not null default 14 check (days > 0 and days <= 30),
  used boolean not null default false,
  used_at timestamptz,
  expires_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists subscription_recovery_codes_user_idx
  on public.subscription_recovery_codes (user_id, used, created_at desc);

create index if not exists subscription_recovery_codes_code_idx
  on public.subscription_recovery_codes (code);

alter table public.subscription_recovery_codes enable row level security;

drop policy if exists "Users can read own recovery codes"
  on public.subscription_recovery_codes;
create policy "Users can read own recovery codes"
  on public.subscription_recovery_codes for select
  to authenticated
  using (auth.uid() = user_id or public.is_admin());

-- No insert/update/delete policy for authenticated users:
--   * codes are inserted by the admin-mutate edge function (service role)
--   * redemption is handled by the redeem-recovery-code edge function (service
--     role), which verifies the code belongs to the caller before marking it used

insert into supabase_migrations.schema_migrations (version, name, statements, created_by)
values (
  '20261123000000',
  '20261123000000_subscription_recovery_codes',
  array['-- 20261123000000_subscription_recovery_codes']::text[],
  'opencode-controlled-apply'
)
on conflict (version) do nothing;
